/**
 * `lib/domain/locations.ts` — the spot location directory (rev. 5.3 §11 P1).
 *
 * This module is the **single source of truth** for the spot inventory. Three
 * things are generated from or checked against it, and none of them owns a copy:
 *
 *   - `supabase/migrations/0004_spot_locations_directory.sql` — generated by
 *     `scripts/seed-locations.mjs`, which `tests/spot-locations-directory.test.mjs`
 *     re-runs and compares byte-for-byte against the committed file. The SQL and
 *     this array therefore cannot drift apart without a red test.
 *   - `src/lib/spot-directory.ts` — the presentation adapter. It maps this array
 *     into the `DirectorySpot` shape the existing components consume; it no
 *     longer holds spot data.
 *   - the legacy `/slug_pickup/**` inventory in `src/data/legacy-site-content.json`,
 *     every spot slug of which must appear below (same test).
 *
 * BOUNDARY (rev. 5.3 §8, enforced by `tests/domain-boundaries.test.mjs`)
 * ---------------------------------------------------------------------------
 * `lib/domain/**` imports `lib/supabase` only — never React, never `lib/ai`. So
 * the inventory lives here as committed data rather than being read from the
 * legacy JSON at runtime: the domain layer does not reach outward, and a
 * directory that a rendering module could edit is not a directory.
 *
 * SLUGS: `slug` vs. `routeSlug`
 * ---------------------------------------------------------------------------
 * `slug` is the canonical lower-case key. It is what the database stores, what
 * the legacy `/slug_pickup/<slug>/` URLs used, and what every lookup normalises
 * to. `routeSlug` preserves the historical casing this app already serves at
 * `/spots/<routeSlug>` (e.g. `Horner-Rd`). They differ only in case, but the
 * distinction is load-bearing: collapsing them would change live URLs, and
 * collapsing them the other way would make the database key case-sensitive.
 *
 * COORDINATES ARE NULLABLE, DELIBERATELY
 * ---------------------------------------------------------------------------
 * Four spots carry `latitude: null, longitude: null` — the four that exist only
 * in the legacy inventory. Their legacy pages publish no coordinates, and this
 * repo does not invent data. `null` is the honest value; a plausible-looking
 * guess would be indistinguishable from a surveyed one. See `Docs/DECISIONS.md`
 * D-31.
 */

export type SpotCorridor = 'I-395 / I-95' | 'I-66'
export type SpotDirection = 'Morning' | 'Afternoon'

/**
 * A spot's media asset, self-hosted. **A transit diagram, not a photograph.**
 *
 * NOT a database column, deliberately. `0004_spot_locations_directory.sql` is
 * generated from this file by `scripts/seed-locations.mjs` and guarded
 * byte-for-byte, so a field that entered `SEED_COLUMNS` would regenerate it.
 * Nothing queries by image and no RLS decision attaches to a static asset path,
 * so this lives in the domain module and `0004` applies untouched (issue #18).
 *
 * `src` is always a path under `public/`. Never a remote URL: a hotlink to
 * sluglines.com dies the day WordPress is cancelled, which is the point of the
 * migration.
 *
 * WHAT THESE FILES ARE, AND WHAT THEY ARE NOT
 * ---------------------------------------------------------------------------
 * `Docs/asset-register.md` classifies all 27 legacy assets: 12 Google Maps
 * aerials, 8 third-party transit or parking schematics, 6 dated route-change
 * notices, 1 promotional flyer, and **zero photographs of a location**. D-39
 * declined to migrate any of them. D-58 migrates **only the 8 schematics** —
 * drawn agency lot diagrams with bus-bay listings, space counts and legends —
 * and holds the other 19 out: the Google aerials carry Google's own credit and
 * its terms, the notices are 2018-2019 and would render as current, and the
 * flyer is a marketing graphic with a contact address on it.
 *
 * So this field is a **transit diagram**, never a photograph. A diagram of a lot
 * is useful orientation; the same file captioned as a photograph would claim a
 * currency and an authorship it does not have — the same failure as a guessed
 * coordinate (D-31) or a fabricated count (D-33). #26 still tracks sourcing real
 * photographs, and this field is not it.
 */
export interface SpotImage {
  /** Path under `public/`, e.g. `/spots/horner-rd.jpg`. Never a remote URL. */
  src: string
  /** Intrinsic pixel size, so `next/image` reserves the box and CLS stays at 0. */
  width: number
  height: number
  /** Describes the spot for a screen reader, not the file. */
  alt: string
  /** Provenance: the legacy URL this file came from. Asserted against LEGACY_IMAGE_PREFIX. */
  sourceUrl: string
  /** ISO date the file was pulled from the legacy site. */
  fetchedAt: string
}

export interface SpotLocation {
  /** Canonical lower-case key: the database key and the legacy URL slug. */
  slug: string
  /** Case-preserved path segment this app serves today. */
  routeSlug: string
  name: string
  corridor: SpotCorridor
  direction: SpotDirection
  county: string
  destination: string
  description: string
  /** `null` where no surveyed coordinate exists. Never guessed. */
  latitude: number | null
  longitude: number | null
  /** Whether a line is believed to be running. Inactive spots stay in the directory. */
  active: boolean
  /**
   * Where this record's operational facts came from and how current they are
   * (issue #36). Required, not optional: an unstated provenance is precisely the
   * problem this models — it renders as confidence the record has not earned.
   */
  provenance: SpotProvenance
  peakHours?: string
  parking?: string
  linesFrom?: string[]
  linesTo?: string[]
  fbUrl?: string
  notes?: string
  /** Absent where the legacy page published no diagram. Never a stand-in. */
  image?: SpotImage
}

/**
 * Publication state for a spot's operational facts — `peakHours`, `parking`,
 * `linesFrom`/`linesTo`, `description` (issue #36).
 *
 * Salvaged from `codex/phase-1`'s `Docs/content-sources.md` during the #11
 * triage. The problem it solves is the one this repo already takes seriously
 * everywhere else: a commuter reading "peak hours 5:30–9:00" cannot tell whether
 * that was confirmed last month or scraped from a 2018 post, because the app
 * renders both with identical authority. Null coordinates are never guessed
 * (D-31) and counts render `unavailable` rather than a fabricated zero (D-33);
 * directory facts were the remaining surface with no honesty mechanism.
 *
 *   verified            Confirmed against a current primary source, or a dated
 *                       on-site review by an editor.
 *   community-reported  Recently reported, not yet corroborated by a primary
 *                       source.
 *   needs-review        Useful orientation whose current operation has not been
 *                       confirmed. The honest state for anything inherited.
 *   historical          Retained for context, never presented as current
 *                       instructions.
 *
 * SOURCE HIERARCHY, strongest first: government or transit-operator pages; then
 * current on-site signage confirmed by an editor; then corroborated community
 * reports; then legacy Sluglines material, which is background and discovery
 * only and never on its own sufficient for `verified`.
 */
export type SpotFactState = 'verified' | 'community-reported' | 'needs-review' | 'historical'

export interface SpotProvenance {
  state: SpotFactState
  /** Where the operational facts came from. Free text, but name a real source. */
  source: string
  /**
   * ISO date the facts were last checked against that source — the date of the
   * *check*, not of the import. Absent where no check has ever happened, which is
   * different from a check that found nothing and must not be back-filled with an
   * import date to make the record look attended to.
   */
  checkedAt?: string
}

/**
 * The states whose facts must not be presented as current instructions without a
 * qualifier. `verified` is deliberately absent: a verified fact needs no badge,
 * which is what keeps the badge meaningful rather than decorative.
 */
export function needsFreshnessQualifier(spot: Pick<SpotLocation, 'provenance'>): boolean {
  return spot.provenance.state !== 'verified'
}

/**
 * The only path a migrated image may have come from (issue #18).
 *
 * Deliberately the narrow `slugging_locations/` path and not `images/`. Three
 * spots publish their asset one directory up, and all three are Google Maps
 * aerials that D-58 declined to migrate; widening the prefix to admit them would
 * remove the guard at the moment it was doing its job. Some legacy pages also
 * embed an `lh5.googleusercontent.com` commenter avatar, which is a person, not
 * a spot.
 */
export const LEGACY_IMAGE_PREFIX = 'https://sluglines.com/images/slugging_locations/'

export function spotImage(slug: string): SpotImage | undefined {
  return findSpotLocation(slug)?.image
}

