/** Asserted against the seeded row count by the migration and by its test. */
export const SPOT_LOCATION_COUNT = SPOT_LOCATIONS.length

const BY_SLUG: ReadonlyMap<string, SpotLocation> = new Map(
  SPOT_LOCATIONS.map((location) => [location.slug, location])
)

/**
 * Slugs are compared case-insensitively everywhere. The legacy site used
 * lower-case URLs and this app serves mixed case, so a caller may hold either.
 */
export function canonicalSlug(slug: string) {
  return slug.trim().toLowerCase()
}

export function findSpotLocation(slug: string): SpotLocation | undefined {
  return BY_SLUG.get(canonicalSlug(slug))
}

export function hasSpotLocation(slug: string) {
  return BY_SLUG.has(canonicalSlug(slug))
}

export function activeSpotLocations() {
  return SPOT_LOCATIONS.filter((location) => location.active)
}

export function inactiveSpotLocations() {
  return SPOT_LOCATIONS.filter((location) => !location.active)
}

export function spotLocationsByCorridor(corridor: SpotCorridor) {
  return SPOT_LOCATIONS.filter((location) => location.corridor === corridor)
}

export function spotLocationsByDirection(direction: SpotDirection) {
  return SPOT_LOCATIONS.filter((location) => location.direction === direction)
}

export function spotLocationCounties(locations: readonly SpotLocation[] = SPOT_LOCATIONS) {
  return Array.from(new Set(locations.map((location) => location.county)))
}

export interface SpotLocationCorridorGroup {
  corridor: SpotCorridor
  directions: {
    direction: SpotDirection
    counties: { county: string; locations: SpotLocation[] }[]
  }[]
}

/**
 * Corridor → direction → county, with empty groups dropped. Directions are
 * emitted in `SPOT_DIRECTIONS` order (Morning before Afternoon) rather than in
 * first-seen order, because that is a commute-day ordering and not a data one.
 */
export function groupSpotLocations(
  locations: readonly SpotLocation[] = SPOT_LOCATIONS
): SpotLocationCorridorGroup[] {
  const corridors = SPOT_CORRIDORS.filter((corridor) =>
    locations.some((location) => location.corridor === corridor)
  )

  return corridors.map((corridor) => ({
    corridor,
    directions: SPOT_DIRECTIONS.map((direction) => {
      const inDirection = locations.filter(
        (location) => location.corridor === corridor && location.direction === direction
      )

      return {
        direction,
        counties: spotLocationCounties(inDirection).map((county) => ({
          county,
          locations: inDirection.filter((location) => location.county === county),
        })),
      }
    }).filter((group) => group.counties.length > 0),
  }))
}

export interface SpotCoordinates {
  latitude: number
  longitude: number
}

const EARTH_RADIUS_MILES = 3958.8

function toRadians(value: number) {
  return (value * Math.PI) / 180
}

export function distanceInMiles(from: SpotCoordinates, to: SpotCoordinates) {
  const latitudeDistance = toRadians(to.latitude - from.latitude)
  const longitudeDistance = toRadians(to.longitude - from.longitude)

  const haversine =
    Math.sin(latitudeDistance / 2) ** 2 +
    Math.cos(toRadians(from.latitude)) *
      Math.cos(toRadians(to.latitude)) *
      Math.sin(longitudeDistance / 2) ** 2

  return EARTH_RADIUS_MILES * 2 * Math.atan2(Math.sqrt(haversine), Math.sqrt(1 - haversine))
}

/**
 * Distance from `origin`, or `Infinity` for a spot with no surveyed coordinate.
 * `Infinity` rather than `null` so it sorts last without a special case at every
 * call site — an uncoordinated spot is never the nearest one.
 */
export function spotLocationDistance(location: SpotLocation, origin: SpotCoordinates) {
  if (location.latitude === null || location.longitude === null) {
    return Number.POSITIVE_INFINITY
  }

  return distanceInMiles(origin, { latitude: location.latitude, longitude: location.longitude })
}

export function nearestSpotLocations(
  origin: SpotCoordinates,
  options: { limit?: number; locations?: readonly SpotLocation[] } = {}
) {
  const { limit, locations = SPOT_LOCATIONS } = options

  const ranked = locations
    .map((location) => ({ location, miles: spotLocationDistance(location, origin) }))
    .filter((entry) => Number.isFinite(entry.miles))
    .sort((left, right) => left.miles - right.miles)

  return typeof limit === 'number' ? ranked.slice(0, limit) : ranked
}
